import { Navigate, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom';
import { api } from './lib/api';
import { OwnerPage } from './OwnerPage';
import { FullscreenGallery } from './FullscreenGallery';
import { CustomersPage } from './CustomersPage';
import { BookingV2Page } from './BookingV2Page';
import { GroupDeparturesPage } from './GroupDeparturesPage';
import { AdminGroupsPage } from './AdminGroupsPage';
import { CatalogV6Page } from './CatalogV6Page';
import { SiteTourPage } from './SiteTourPage';
import { AdminCrmPage } from './AdminCrmPage';
import { LanguageSwitcher, useI18n } from './i18n';
import { formatUsd } from '../shared/money';
import type { AnalyticsResponse, AvailabilityDate, BookingDraft, Destination, OrderSummary, Quote, Tour } from '../shared/types';

type Role = 'tourist' | 'manager' | 'admin' | 'owner';
type AppContextValue = {
  booking: BookingDraft;
  setBooking: React.Dispatch<React.SetStateAction<BookingDraft>>;
  latestOrder: OrderSummary | null;
  setLatestOrder: React.Dispatch<React.SetStateAction<OrderSummary | null>>;
  refresh: number;
  bump: () => void;
};

const AppContext = createContext<AppContextValue | null>(null);
const useApp = () => {
  const value = useContext(AppContext);
  if (!value) throw new Error('MAX TOUR app context is unavailable');
  return value;
};

const LOGO_SRC = 'https://static.tildacdn.one/tild3063-6230-4266-b063-313839663461/____1680_x_600_-4.jpg';
const HERO_IMAGE = 'https://cdn.getyourguide.com/image/format%3Dauto%2Cfit%3Dcrop%2Cgravity%3Dcenter%2Cquality%3D80%2Cwidth%3D1200%2Cheight%3D900/tour_img/b774041db08e9e68.jpeg';
const EDITORIAL_IMAGES = [
  'https://www.kkday.com/vi/blog/wp-content/uploads/cap-treo-da-lat-1.jpg',
  'https://cdn.findtour.vn/media/attractions/240420103311/gallery/gia-ve-duong-ham-dat-set-da-lat-1.jpg?mode=crop&quality=95&width=1400',
  'https://photo.znews.vn/w660/Uploaded/spivpdiv/2020_04_26/spychem.jpg',
  'https://heritagevietnamairlines.cdn.vccloud.vn/wp-content/uploads/2025/08/EN-b3f6f4b940d6c88891c7.jpg',
  'https://pystravel.vn/_next/image?q=75&url=https%3A%2F%2Fpystravel.vn%2Fuploads%2Fposts%2Falbums%2F3600%2Fbc72c768097de9a89654c1dd13cae02c.jpg&w=1920',
];

const defaultBooking: BookingDraft = {
  tourId: 'dalat-premium', format: 'group', date: '2026-09-12', adults: 2,
  children: [{ height: 112, age: null }], hotel: 'Amiana Resort', transferZoneId: 'north',
  participants: [{ fullName: '', birthDate: '' }, { fullName: '', birthDate: '' }, { fullName: '', birthDate: '' }],
  contact: { name: '', phone: '', telegram: '' }, paymentChoice: 'deposit', paymentMethod: 'card', source: 'Telegram',
};

function roleFromPath(pathname: string): Role {
  if (pathname.startsWith('/owner')) return 'owner';
  if (pathname.startsWith('/manager') || pathname.startsWith('/channels')) return 'manager';
  if (pathname.startsWith('/admin')) return 'admin';
  return 'tourist';
}

export function PremiumApp() {
  const [booking, setBooking] = useState<BookingDraft>(defaultBooking);
  const [latestOrder, setLatestOrder] = useState<OrderSummary | null>(null);
  const [refresh, setRefresh] = useState(0);
  const [ready, setReady] = useState(false);
  const [error, setError] = useState('');
  useEffect(() => { api.session().then(() => setReady(true)).catch((e) => { setError(e.message || 'Не удалось подключить демо-сессию'); setReady(true); }); }, []);
  const value = useMemo(() => ({ booking, setBooking, latestOrder, setLatestOrder, refresh, bump: () => setRefresh((v) => v + 1) }), [booking, latestOrder, refresh]);
  if (!ready) return <LoadingState title="MAX TOUR" text="Готовим персональный каталог путешествий" />;
  if (error) return <LoadingState title="Не удалось открыть приложение" text={error} action={() => location.reload()} />;
  return <AppContext.Provider value={value}><AppRoutes /></AppContext.Provider>;
}

function LoadingState({ title, text, action }: { title: string; text: string; action?: () => void }) {
  return <main className="px-loading"><div className="px-monogram">MT</div><h1>{title}</h1><p>{text}</p>{action && <button className="px-button px-button-primary" onClick={action}>Повторить</button>}</main>;
}

function AppRoutes() {
  return <Routes>
    <Route path="/bot" element={<Navigate to="/" replace />} />
    <Route path="/" element={<TouristShell><HomePage /></TouristShell>} />
    <Route path="/catalog" element={<TouristShell><CatalogV6Page /></TouristShell>} />
    <Route path="/tour/:id" element={<TouristShell><TourPage /></TouristShell>} />
    <Route path="/site-tour/:slug" element={<TouristShell><SiteTourPage /></TouristShell>} />
    <Route path="/booking" element={<TouristShell><BookingV2Page /></TouristShell>} />
    <Route path="/groups/:tourId" element={<TouristShell><GroupDeparturesPage /></TouristShell>} />
    <Route path="/booking/*" element={<Navigate to="/booking" replace />} />
    <Route path="/trips" element={<TouristShell><TripsPage /></TouristShell>} />
    <Route path="/trips/:id" element={<TouristShell><TripDetailPage /></TouristShell>} />
    <Route path="/help" element={<TouristShell><HelpPage /></TouristShell>} />
    <Route path="/manager" element={<BackofficeShell title="Заказы" role="manager"><ManagerPage /></BackofficeShell>} />
    <Route path="/manager/:id" element={<BackofficeShell title="Заказ" role="manager"><ManagerOrderPage /></BackofficeShell>} />
    <Route path="/manager-customers" element={<BackofficeShell title="Клиенты" role="manager"><CustomersPage /></BackofficeShell>} />
    <Route path="/channels" element={<BackofficeShell title="Каналы продаж" role="manager"><ChannelsPage /></BackofficeShell>} />
    <Route path="/owner" element={<BackofficeShell title="Панель владельца" role="owner"><OwnerPage /></BackofficeShell>} />
    <Route path="/admin" element={<BackofficeShell title="Управление" role="admin"><AdminPage /></BackofficeShell>} />
    <Route path="/admin/tours/:id" element={<BackofficeShell title="Экскурсия" role="admin"><AdminTourPage /></BackofficeShell>} />
    <Route path="/admin/schedule" element={<BackofficeShell title="Расписание и акции" role="admin"><SchedulePage /></BackofficeShell>} />
    <Route path="/admin/groups" element={<BackofficeShell title="Групповые заявки" role="admin"><AdminGroupsPage /></BackofficeShell>} />
    <Route path="/admin/crm" element={<BackofficeShell title="CRM и рассылки" role="admin"><AdminCrmPage /></BackofficeShell>} />
    <Route path="/admin/analytics" element={<BackofficeShell title="Аналитика" role="admin"><AnalyticsPage /></BackofficeShell>} />
    <Route path="/admin/directions" element={<BackofficeShell title="Направления" role="admin"><DirectionsPage /></BackofficeShell>} />
    <Route path="*" element={<Navigate to="/" replace />} />
  </Routes>;
}

function Logo() {
  const [failed, setFailed] = useState(false);
  return <div className="px-logo-wrap">{!failed ? <img className="px-logo-image px-logo-official" src={LOGO_SRC} alt="MAX TOUR" onError={() => setFailed(true)} /> : <div className="px-logo-text"><b>MAX TOUR</b><span>VIETNAM</span></div>}</div>;
}

function Header({ title }: { title?: string }) {
  const [open, setOpen] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();
  const role = roleFromPath(location.pathname);
  const { t } = useI18n();
  const tr = (key: string, fallback: string) => role === 'tourist' ? t(key, fallback) : fallback;
  const goRole = (next: Role) => { setOpen(false); navigate(next === 'manager' ? '/manager' : next === 'admin' ? '/admin' : next === 'owner' ? '/owner' : '/'); };
  return <><header className="px-header"><button className="px-brand-button" onClick={() => navigate('/')} aria-label="MAX TOUR"><Logo /></button>{title && <span className="px-header-title">{title}</span>}{role === 'tourist' && <LanguageSwitcher />}<button className={`px-menu-button ${open ? 'is-open' : ''}`} onClick={() => setOpen(!open)} aria-label="Menu" aria-expanded={open}><i /><i /><i /></button></header>{open && <div className="px-menu-backdrop" onClick={() => setOpen(false)} />}<aside className={`px-drawer ${open ? 'is-open' : ''}`}><div className="px-drawer-top"><Logo /><button className="px-close" onClick={() => setOpen(false)}>×</button></div><nav className="px-menu-list"><MenuLink label={tr('nav.home','Главная')} subtitle={tr('nav.home.sub','Вдохновение и подборки')} onClick={() => { setOpen(false); navigate('/'); }} /><MenuLink label={tr('nav.tours','Экскурсии')} subtitle={tr('nav.tours.sub','Каталог по направлениям')} onClick={() => { setOpen(false); navigate('/catalog'); }} /><MenuLink label={tr('nav.trips','Мои поездки')} subtitle={tr('nav.trips.sub','Брони и детали путешествий')} onClick={() => { setOpen(false); navigate('/trips'); }} /><MenuLink label={tr('nav.help','Помощь')} subtitle={tr('nav.help.sub','Условия, оплата и поддержка')} onClick={() => { setOpen(false); navigate('/help'); }} /></nav><div className="px-drawer-separator" /><div className="px-demo-kicker">ДЕМО · РОЛЬ</div><div className="px-role-stack"><button className={role === 'tourist' ? 'active' : ''} onClick={() => goRole('tourist')}><b>Турист</b><span>Каталог и бронирование</span></button><button className={role === 'manager' ? 'active' : ''} onClick={() => goRole('manager')}><b>Менеджер</b><span>Заказы и подтверждения</span></button><button className={role === 'admin' ? 'active' : ''} onClick={() => goRole('admin')}><b>Администратор</b><span>Каталог, цены, расписание</span></button><button className={role === 'owner' ? 'active' : ''} onClick={() => goRole('owner')}><b>Владелец</b><span>Показатели и правила команды</span></button></div><button className="px-channel-link" onClick={() => { setOpen(false); navigate('/channels'); }}>Tilda + Telegram → единая система</button><p className="px-drawer-note">Переключатель виден только в демонстрационной версии.</p></aside></>;
}

function MenuLink({ label, subtitle, onClick }: { label: string; subtitle: string; onClick: () => void }) { return <button onClick={onClick}><b>{label}</b><span>{subtitle}</span><em>→</em></button>; }

function TouristShell({ children }: { children: React.ReactNode }) {
  const navigate = useNavigate();
  const path = useLocation().pathname;
  const { t } = useI18n();
  const items = [
    ['/', t('nav.home'), '⌂'],
    ['/catalog', t('nav.tours'), '◇'],
    ['/trips', t('nav.trips'), '✦'],
    ['/help', t('nav.help'), '?'],
  ];
  return <div className="px-app"><Header /><main className="px-content">{children}</main><nav className="px-bottom-nav">{items.map(([to, label, icon]) => <button key={to} className={(to === '/' ? path === '/' : path.startsWith(to)) ? 'active' : ''} onClick={() => navigate(to)}><span>{icon}</span><small>{label}</small></button>)}</nav></div>;
}

function BackofficeShell({ title, role, children }: { title: string; role: Role; children: React.ReactNode }) {
  const navigate = useNavigate();
  const roleLabel = role === 'manager' ? 'MANAGER DEMO' : role === 'admin' ? 'ADMIN DEMO' : 'OWNER DEMO';
  const tabs = role === 'manager' ? <><button onClick={() => navigate('/manager')}>Заказы</button><button onClick={() => navigate('/manager-customers')}>Клиенты</button><button onClick={() => navigate('/channels')}>Интеграции</button></> : role === 'admin' ? <><button onClick={() => navigate('/admin')}>Каталог</button><button onClick={() => navigate('/admin/schedule')}>Расписание</button><button onClick={() => navigate('/admin/groups')}>Группы</button><button onClick={() => navigate('/admin/crm')}>CRM</button><button onClick={() => navigate('/admin/analytics')}>Аналитика</button><button onClick={() => navigate('/admin/directions')}>Направления</button></> : <><button onClick={() => navigate('/owner')}>Обзор</button><button onClick={() => navigate('/manager')}>Очередь менеджера</button><button onClick={() => navigate('/admin')}>Управление продуктом</button><button onClick={() => navigate('/channels')}>Каналы продаж</button></>;
  return <div className="px-app px-backoffice"><Header title={title} /><main className="px-content px-wide"><section className="px-office-hero"><div><span className="px-kicker">MAX TOUR · {roleLabel}</span><h1>{title}</h1></div><span className="px-demo-pill">ДЕМО-ДАННЫЕ</span></section><nav className="px-office-tabs">{tabs}</nav>{children}</main></div>;
}

function useTours(admin = false) {
  const { refresh } = useApp(); const [items, setItems] = useState<Tour[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const load = () => { setLoading(true); (admin ? api.adminTours() : api.tours()).then((r) => setItems(r.items)).catch((e) => setError(e.message)).finally(() => setLoading(false)); };
  useEffect(load, [admin, refresh]); return { items, loading, error, reload: load };
}

function HomePage() {
  const navigate = useNavigate();
  const { t, locale } = useI18n();
  const { items, loading, error } = useTours();
  const [destinations, setDestinations] = useState<Destination[]>([]);
  const [trips, setTrips] = useState<OrderSummary[]>([]);
  useEffect(() => { api.destinations().then((r) => setDestinations(r.items)); api.trips().then((r) => setTrips(r.items)); }, [locale]);
  const flagship = items.find((tour) => tour.id === 'dalat-premium') ?? items[0];
  return <><section className="px-hero"><img src={flagship?.images?.[0] || HERO_IMAGE} alt="MAX TOUR Vietnam" /><div className="px-hero-shade" /><div className="px-hero-copy"><span className="px-kicker px-kicker-light">MAX TOUR · VIETNAM</span><h1>{t('home.hero.1')}<br />{t('home.hero.2')}<br />{t('home.hero.3')}</h1><p>{t('home.hero.text')}</p><div className="px-hero-actions"><button className="px-button px-button-light" onClick={() => navigate('/catalog')}>{t('home.choose')}</button><button className="px-text-button" onClick={() => navigate('/catalog')}>{t('home.premium')}</button></div></div><div className="px-hero-trust"><span><b>150+</b> {t('home.tours')}</span><span><b>5</b> {t('home.destinations')}</span><span><b>24/7</b> {t('home.online')}</span></div></section><section className="px-section px-intro-grid"><div><span className="px-kicker">{t('home.forYou')}</span><h2>{t('home.journeyTitle')}</h2></div><p>{t('home.journeyText')}</p></section><section className="px-section px-destination-strip">{destinations.map((destination, index) => <button key={destination.id} onClick={() => navigate('/catalog')}><span>0{index + 1}</span><b>{destination.name}</b><em>→</em></button>)}<button className="premium" onClick={() => navigate('/catalog')}><span>06</span><b>{t('home.premiumShort')}</b><em>→</em></button></section>{flagship && <section className="px-section px-featured"><div className="px-featured-media"><img src={flagship.images[1] || flagship.images[0]} alt={flagship.title} /><span className="px-floating-label">SIGNATURE EXPERIENCE</span></div><div className="px-featured-copy"><span className="px-kicker">{t('home.premiumLabel')}</span><h2>{flagship.title}</h2><p>{flagship.description}</p><div className="px-feature-meta"><span>{t('home.pickup')} {flagship.pickup || t('tour.byProgram')}</span><span>{flagship.program.length} {t('home.stops')}</span><span>{t('home.from')} {formatUsd(flagship.pricingRules.adultMinor ?? flagship.pricingRules.adultFromMinor ?? 0)}</span></div><button className="px-button px-button-dark" onClick={() => navigate(`/tour/${flagship.id}`)}>{t('home.openProgram')}</button></div></section>}<section className="px-section"><div className="px-section-heading"><div><span className="px-kicker">{t('home.collection')}</span><h2>{t('home.popular')}</h2></div><button className="px-link" onClick={() => navigate('/catalog')}>{t('home.all')}</button></div>{error && <Notice>{error}</Notice>}{loading ? <SkeletonCards /> : <div className="px-tour-grid">{items.slice(0, 6).map((tour, index) => <TourCard key={tour.id} tour={tour} index={index} />)}</div>}</section><section className="px-section px-service-grid"><article><span>01</span><h3>{t('home.smallGroups')}</h3><p>{t('home.smallGroupsText')}</p></article><article><span>02</span><h3>{t('home.private')}</h3><p>{t('home.privateText')}</p></article><article><span>03</span><h3>{t('home.hotelPickup')}</h3><p>{t('home.hotelPickupText')}</p></article><article><span>04</span><h3>{t('home.clearPrice')}</h3><p>{t('home.clearPriceText')}</p></article></section>{trips[0] && <section className="px-section"><div className="px-trip-banner"><div><span className="px-kicker">{t('home.nextTrip')}</span><h3>{trips[0].tourTitle}</h3><p>{trips[0].selectedDate} · {trips[0].status}</p></div><button onClick={() => navigate(`/trips/${trips[0].id}`)}>{t('common.open')}</button></div></section>}</>;
}

function SkeletonCards() { return <div className="px-tour-grid">{[1, 2, 3, 4].map((n) => <div className="px-skeleton" key={n} />)}</div>; }
function TourCard({ tour, index }: { tour: Tour; index: number }) { const navigate = useNavigate(); const price = tour.pricingRules.adultMinor ?? tour.pricingRules.adultFromMinor ?? 0; return <article className={`px-tour-card ${index === 0 ? 'px-tour-card-large' : ''}`} onClick={() => navigate(`/tour/${tour.id}`)}><div className="px-tour-image"><img src={tour.images[index % Math.max(1, tour.images.length)] || tour.images[0]} alt={tour.title} /><div className="px-image-gradient" />{tour.promo?.enabled && <span className="px-promo">DEMO PROMO · {tour.promo.label || tour.promo.value}</span>}<span className="px-card-number">0{index + 1}</span></div><div className="px-tour-copy"><span className="px-kicker">{tour.direction} · {tour.category}</span><h3>{tour.title}</h3><div className="px-tour-footer"><span>{tour.priceMode === 'fixed' ? '' : 'от '}{formatUsd(price)}</span><em>Подробнее →</em></div></div></article>; }

function CatalogPage() {
  const params = new URLSearchParams(useLocation().search); const { items, loading, error } = useTours(); const [query, setQuery] = useState(''); const [filter, setFilter] = useState(params.get('filter') || 'Все'); const filters = ['Все', 'Нячанг', 'Дананг', 'Фукуок', 'Муйне/Фантьет', 'Ханой', 'Премиум экскурсии'];
  const shown = items.filter((tour) => (filter === 'Все' || tour.direction === filter || tour.category === filter) && (!query || tour.title.toLowerCase().includes(query.toLowerCase())));
  return <><section className="px-page-title"><span className="px-kicker">MAX TOUR COLLECTION</span><h1>Экскурсии</h1><p>От городских прогулок до премиальных маршрутов на несколько дней.</p></section><section className="px-catalog-controls"><label><span>Поиск</span><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Например, Далат" /></label><div className="px-filter-row">{filters.map((item) => <button key={item} className={filter === item ? 'active' : ''} onClick={() => setFilter(item)}>{item}</button>)}</div></section>{error && <Notice>{error}</Notice>}{loading ? <SkeletonCards /> : <div className="px-tour-grid px-catalog-grid">{shown.map((tour, index) => <TourCard key={tour.id} tour={tour} index={index} />)}</div>}</>;
}

function TourPage() {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const { refresh } = useApp();
  const { t, locale } = useI18n();
  const [tour, setTour] = useState<Tour | null>(null);
  const [error, setError] = useState('');
  useEffect(() => { api.tour(id).then((r) => { setTour(r.item); api.event('view_tour', r.item.id); }).catch((e) => setError(e.message)); }, [id, refresh, locale]);
  if (error) return <Notice>{error}</Notice>;
  if (!tour) return <SkeletonCards />;
  const adultPrice = tour.pricingRules.adultMinor ?? tour.pricingRules.adultFromMinor ?? 0;
  const begin = () => { api.event('start_booking', tour.id); navigate(`/booking?tourId=${tour.id}`); };
  return <><section className="px-detail-hero"><img src={tour.images[0]} alt={tour.title} /><div className="px-hero-shade" /><button className="px-back" onClick={() => navigate('/catalog')}>←</button><div className="px-detail-title"><span className="px-kicker px-kicker-light">{tour.direction} · {tour.category}</span><h1>{tour.title}</h1><div><b>{tour.priceMode === 'fixed' ? '' : t('tour.from') + ' '}{formatUsd(adultPrice)}</b><span>{t('tour.adult')}</span></div></div></section><section className="px-section px-detail-intro"><div><span className="px-kicker">{t('tour.about')}</span><h2>{t('tour.detailsTitle')}</h2></div><p>{tour.description}</p></section><section className="px-section px-fact-row"><div><span>{t('tour.pickup')}</span><b>{tour.pickup || t('tour.byProgram')}</b></div><div><span>{t('tour.back')}</span><b>{tour.back || t('tour.byProgram')}</b></div><div><span>{t('tour.format')}</span><b>{t('tour.formatValue')}</b></div></section><section className="px-section"><div className="px-section-heading"><div><span className="px-kicker">{t('tour.gallery')}</span><h2>{tour.images.length} {t('tour.frames')}</h2></div></div><FullscreenGallery images={tour.images} title={tour.title} labels={tour.program.map((item) => item.split(" — ")[0])} /></section><section className="px-section px-program-grid"><div><span className="px-kicker">{t('tour.program')}</span><h2>{t('tour.steps')}</h2></div><ol>{tour.program.map((item, index) => <li key={item}><span>{String(index + 1).padStart(2, '0')}</span><p>{item}</p></li>)}</ol></section><section className="px-section px-included"><div><span className="px-kicker">{t('tour.included')}</span><h2>{t('tour.inTrip')}</h2></div><ul>{tour.included.map((item) => <li key={item}>✓ {item}</li>)}</ul></section>{tour.extraCosts.length > 0 && <section className="px-section px-note-panel"><span className="px-kicker">{t('tour.extra')}</span>{tour.extraCosts.map((item) => <p key={item}>{item}</p>)}</section>}{tour.whatToTake.length > 0 && <section className="px-section px-included px-take-section"><div><span className="px-kicker">{t('tour.take')}</span><h2>{t('tour.before')}</h2></div><ul>{tour.whatToTake.map((item) => <li key={item}>• {item}</li>)}</ul></section>}<section className="px-section px-source-note"><span>{t('tour.source')}</span><a href={tour.sourceUrl} target="_blank" rel="noreferrer">{t('tour.official')}</a></section><div className="px-sticky-cta"><div><span>{t('tour.from')}</span><b>{formatUsd(adultPrice)}</b></div><button className="px-button px-button-primary" onClick={begin}>{t('tour.chooseFormat')}</button></div></>;
}

function BookingPage() {
  const navigate = useNavigate(); const { booking, setBooking, latestOrder, setLatestOrder } = useApp(); const [tour, setTour] = useState<Tour | null>(null); const [availability, setAvailability] = useState<AvailabilityDate[]>([]); const [step, setStep] = useState(1); const [quote, setQuote] = useState<Quote | null>(null); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  useEffect(() => { api.tour(booking.tourId).then((r) => setTour(r.item)); api.availability(booking.tourId).then((r) => setAvailability(r.items)); }, [booking.tourId]);
  const people = booking.adults + booking.children.length;
  const resizeParticipants = (nextAdults: number, nextChildren: number) => { setBooking((current) => ({ ...current, adults: nextAdults, children: Array.from({ length: nextChildren }, (_, i) => current.children[i] || { height: 112, age: null }), participants: Array.from({ length: nextAdults + nextChildren }, (_, i) => current.participants[i] || { fullName: '', birthDate: '' }) })); };
  const getQuote = async () => { setBusy(true); setError(''); try { const result = await api.quote(booking); setQuote(result.quote); setStep(4); } catch (e: any) { setError(e.message || 'Проверьте данные'); } finally { setBusy(false); } };
  const createOrder = async () => { setBusy(true); setError(''); try { const result = await api.createOrder(booking, `premium-order-${Date.now()}`); setLatestOrder(result.order); setStep(5); } catch (e: any) { setError(e.message || 'Не удалось оформить бронь'); } finally { setBusy(false); } };
  const pay = async () => { if (!latestOrder) return; setBusy(true); setError(''); try { const result = await api.pay(latestOrder.id, `premium-pay-${latestOrder.id}`); setLatestOrder(result.order); setStep(6); } catch (e: any) { setError(e.message || 'Не удалось выполнить DEMO-оплату'); } finally { setBusy(false); } };
  if (!tour) return <SkeletonCards />;
  return <section className="px-booking"><div className="px-booking-head"><button className="px-back-inline" onClick={() => step > 1 ? setStep(step - 1) : navigate(`/tour/${tour.id}`)}>← Назад</button><span>Шаг {Math.min(step, 5)} из 5</span></div><div className="px-progress"><i style={{ width: `${Math.min(step, 5) * 20}%` }} /></div><span className="px-kicker">{tour.title}</span>{step === 1 && <div className="px-booking-card"><h1>Когда едем?</h1><p>Выберите демонстрационную дату. Реальное наличие мест подключается к рабочему расписанию.</p><div className="px-date-grid">{availability.map((item) => <button key={item.date} className={booking.date === item.date ? 'active' : ''} onClick={() => setBooking((b) => ({ ...b, date: item.date }))}><b>{item.date}</b><span>{item.label}</span><em>DEMO</em></button>)}</div><button className="px-button px-button-primary px-block" disabled={!booking.date} onClick={() => setStep(2)}>Продолжить</button></div>}{step === 2 && <div className="px-booking-card"><h1>Кто путешествует?</h1><div className="px-counter-list"><Counter label="Взрослые" value={booking.adults} min={1} onChange={(v) => resizeParticipants(v, booking.children.length)} /><Counter label="Дети" note="Тариф зависит от параметров экскурсии" value={booking.children.length} min={0} onChange={(v) => resizeParticipants(booking.adults, v)} /></div>{booking.children.map((child, index) => <label className="px-field" key={index}><span>Рост ребёнка {index + 1}, см</span><input type="number" value={child.height ?? ''} onChange={(e) => setBooking((b) => ({ ...b, children: b.children.map((c, i) => i === index ? { ...c, height: Number(e.target.value) } : c) }))} /></label>)}<button className="px-button px-button-primary px-block" onClick={() => setStep(3)}>Продолжить · {people} чел.</button></div>}{step === 3 && <div className="px-booking-card"><h1>Детали поездки</h1><label className="px-field"><span>Отель</span><input value={booking.hotel} onChange={(e) => setBooking((b) => ({ ...b, hotel: e.target.value, transferZoneId: /amiana|alibu|do/i.test(e.target.value) ? 'north' : undefined }))} placeholder="Название отеля" /></label><div className="px-participants">{booking.participants.map((person, index) => <div key={index}><b>{index + 1}. Путешественник</b><label className="px-field"><span>Имя и фамилия</span><input value={person.fullName} onChange={(e) => setBooking((b) => ({ ...b, participants: b.participants.map((p, i) => i === index ? { ...p, fullName: e.target.value } : p) }))} /></label><label className="px-field"><span>Дата рождения</span><input type="date" value={person.birthDate || ''} onChange={(e) => setBooking((b) => ({ ...b, participants: b.participants.map((p, i) => i === index ? { ...p, birthDate: e.target.value } : p) }))} /></label></div>)}</div><div className="px-divider" /><h3>Контакт для подтверждения</h3><label className="px-field"><span>Имя</span><input value={booking.contact.name} onChange={(e) => setBooking((b) => ({ ...b, contact: { ...b.contact, name: e.target.value } }))} /></label><label className="px-field"><span>Телефон</span><input value={booking.contact.phone} onChange={(e) => setBooking((b) => ({ ...b, contact: { ...b.contact, phone: e.target.value } }))} /></label><button className="px-button px-button-primary px-block" disabled={busy} onClick={getQuote}>{busy ? 'Считаем…' : 'Рассчитать стоимость'}</button></div>}{step === 4 && quote && <div className="px-booking-card"><span className="px-demo-pill">DEMO QUOTE · SERVER</span><h1>{formatUsd(quote.totalMinor)}</h1><p>Итог рассчитан сервером по выбранному составу и зоне трансфера.</p><div className="px-quote-lines">{quote.lines.map((line) => <div key={line.label}><span>{line.label}</span><b>{formatUsd(line.amountMinor)}</b></div>)}</div><div className="px-choice-row"><button className={booking.paymentChoice === 'deposit' ? 'active' : ''} onClick={() => setBooking((b) => ({ ...b, paymentChoice: 'deposit' }))}><b>Предоплата</b><span>{formatUsd(quote.payNowMinor)} · DEMO 30%</span></button><button className={booking.paymentChoice === 'full' ? 'active' : ''} onClick={() => setBooking((b) => ({ ...b, paymentChoice: 'full' }))}><b>Полностью</b><span>{formatUsd(quote.totalMinor)}</span></button></div><button className="px-button px-button-primary px-block" disabled={busy} onClick={createOrder}>Оформить бронирование</button></div>}{step === 5 && latestOrder && <div className="px-booking-card"><span className="px-demo-pill">ДЕМО · СПИСАНИЯ НЕ БУДЕТ</span><h1>Оплата</h1><p>В боевой версии здесь подключается выбранный MAX TOUR платёжный провайдер. Комиссии и конкретный сервис в демо не выдумываются.</p><div className="px-payment-methods">{[['card','Банковская карта'],['sbp','СБП / перевод'],['transfer','Банковский перевод'],['cash','Наличными']].map(([id, label]) => <button key={id} className={booking.paymentMethod === id ? 'active' : ''} onClick={() => setBooking((b) => ({ ...b, paymentMethod: id as BookingDraft['paymentMethod'] }))}>{label}<span>→</span></button>)}</div><button className="px-button px-button-primary px-block" disabled={busy} onClick={pay}>{busy ? 'Обрабатываем…' : `Оплатить ${formatUsd(quote?.payNowMinor || latestOrder.totalMinor)} — DEMO`}</button></div>}{step === 6 && latestOrder && <div className="px-booking-card px-success-card"><div className="px-success-icon">✓</div><span className="px-kicker">БРОНИРОВАНИЕ ОФОРМЛЕНО</span><h1>{latestOrder.tourTitle}</h1><p>Предоплата получена — DEMO. Заказ уже доступен в интерфейсе менеджера.</p><div className="px-order-summary"><div><span>Заказ</span><b>{latestOrder.id}</b></div><div><span>Дата</span><b>{latestOrder.selectedDate}</b></div><div><span>Оплачено</span><b>{formatUsd(latestOrder.paidMinor)}</b></div><div><span>Осталось</span><b>{formatUsd(latestOrder.remainingMinor)}</b></div></div><button className="px-button px-button-dark px-block" onClick={() => navigate(`/trips/${latestOrder.id}`)}>Открыть поездку</button></div>}{error && <Notice>{error}</Notice>}</section>;
}

function Counter({ label, note, value, min, onChange }: { label: string; note?: string; value: number; min: number; onChange: (value: number) => void }) { return <div className="px-counter"><div><b>{label}</b>{note && <span>{note}</span>}</div><div><button onClick={() => onChange(Math.max(min, value - 1))}>−</button><strong>{value}</strong><button onClick={() => onChange(value + 1)}>+</button></div></div>; }

function TripsPage() {
  const navigate = useNavigate();
  const { t, locale } = useI18n();
  const [items, setItems] = useState<OrderSummary[]>([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => { setLoading(true); api.trips().then((r) => setItems(r.items)).finally(() => setLoading(false)); }, [locale]);
  return <><section className="px-page-title"><span className="px-kicker">{t('trips.kicker')}</span><h1>{t('trips.title')}</h1><p>{t('trips.subtitle')}</p></section>{loading ? <SkeletonCards /> : items.length ? <div className="px-trip-list">{items.map((order) => <button key={order.id} onClick={() => navigate(`/trips/${order.id}`)}><div><span className="px-status">{order.status}</span><h3>{order.tourTitle}</h3><p>{order.selectedDate} · {order.hotel}</p></div><div><b>{formatUsd(order.totalMinor)}</b><span>→</span></div></button>)}</div> : <div className="px-empty"><h3>{t('trips.empty')}</h3><p>{t('trips.emptyText')}</p><button className="px-button px-button-primary" onClick={() => navigate('/catalog')}>{t('trips.choose')}</button></div>}</>;
}

function TripDetailPage() {
  const { id = '' } = useParams();
  const { t, locale } = useI18n();
  const [order, setOrder] = useState<OrderSummary | null>(null);
  const [error, setError] = useState('');
  useEffect(() => { api.order(id).then((r) => setOrder(r.order)).catch((e) => setError(e.message)); }, [id, locale]);
  if (error) return <Notice>{error}</Notice>;
  if (!order) return <SkeletonCards />;
  return <><section className="px-page-title"><span className="px-status">{order.status}</span><h1>{order.tourTitle}</h1><p>{t('trip.order')} {order.id}</p></section><section className="px-order-detail-grid"><Detail label={t('trip.date')} value={order.selectedDate} /><Detail label={t('trip.participants')} value={order.participantsSummary} /><Detail label={t('trip.hotel')} value={order.hotel} /><Detail label={t('trip.source')} value={order.source} /><Detail label={t('booking.paid')} value={formatUsd(order.paidMinor)} /><Detail label={t('booking.remaining')} value={formatUsd(order.remainingMinor)} /></section><section className="px-section px-note-panel"><span className="px-kicker">{t('trip.cancelKicker')}</span><p>{t('trip.cancel1')}</p><p>{t('trip.cancel2')}</p><p>{t('trip.cancel3')}</p></section></>;
}

function HelpPage() {
  const { t } = useI18n();
  return <><section className="px-page-title"><span className="px-kicker">MAX TOUR SUPPORT</span><h1>{t('help.title')}</h1><p>{t('help.intro')}</p></section><section className="px-faq"><details open><summary>{t('help.how')}</summary><p>{t('help.howText')}</p></details><details><summary>{t('help.payment')}</summary><p>{t('help.paymentText')}</p></details><details><summary>{t('help.prepay')}</summary><p>{t('help.prepayText')}</p></details><details><summary>{t('help.cancel')}</summary><p>{t('help.cancelText')}</p></details><details><summary>{t('help.group')}</summary><p>{t('help.groupText')}</p></details><details><summary>{t('help.transfer')}</summary><p>{t('help.transferText')}</p></details><details><summary>{t('help.weather')}</summary><p>{t('help.weatherText')}</p></details></section></>;
}

function ManagerPage() { const navigate = useNavigate(); const [items, setItems] = useState<OrderSummary[]>([]); const [filter, setFilter] = useState('Все'); useEffect(() => { api.managerOrders().then((r) => setItems(r.items)); }, []); const shown = items.filter((item) => filter === 'Все' || item.status === filter); const total = items.reduce((sum, item) => sum + item.totalMinor, 0); return <><section className="px-metric-grid"><Metric label="Заказы" value={String(items.length)} note="текущая demo-сессия" /><Metric label="Объём" value={formatUsd(total)} note="DEMO orders" /><Metric label="Каналы" value={String(new Set(items.map((item) => item.source)).size || 2)} note="Telegram + сайт" /></section><div className="px-filter-row px-office-filter">{['Все', 'Новый', 'Оплачено', 'Подтверждено'].map((item) => <button className={filter === item ? 'active' : ''} key={item} onClick={() => setFilter(item)}>{item}</button>)}</div><section className="px-manager-list">{shown.length ? shown.map((order) => <button key={order.id} onClick={() => navigate(`/manager/${order.id}`)}><div className="px-manager-main"><span className="px-status">{order.status}</span><h3>{order.tourTitle}</h3><p>{order.customer} · {order.selectedDate}</p></div><div className="px-manager-side"><b>{formatUsd(order.totalMinor)}</b><span>{order.source}</span><em>→</em></div></button>) : <div className="px-empty"><h3>Заказов с таким статусом нет</h3><p>Создайте заказ в роли туриста — он появится здесь автоматически.</p></div>}</section></>; }

function ManagerOrderPage() {
  const { id = '' } = useParams();
  const [order, setOrder] = useState<OrderSummary | null>(null);
  const [ops,setOps]=useState({assignedManager:'',pickupNote:'',internalNote:'',lastContactAt:null as string|null,updatedAt:null as string|null});
  const [staff,setStaff]=useState<Array<{telegramUserId:string;role:string;displayName:string;active:boolean}>>([]);
  const [workflow,setWorkflow]=useState({operationType:'none',requestedDate:'',reason:'',managerNote:'',workflowStatus:'Нет запроса',updatedAt:null as string|null});
  const [error, setError] = useState(''); const [saved,setSaved]=useState(false); const [workflowSaved,setWorkflowSaved]=useState(false); const [workflowBusy,setWorkflowBusy]=useState(false);
  const load = () => { void Promise.all([api.managerOrder(id),api.managerOps(id),api.orderWorkflow(id),api.managerStaff()]).then(([orderResult,opsResult,workflowResult,staffResult])=>{setOrder(orderResult.order);setOps(opsResult.ops);setWorkflow(workflowResult.workflow);setStaff(staffResult.items)}).catch((e) => setError(e.message)); };
  useEffect(() => { load(); }, [id]);
  const update = async (status: OrderSummary['status']) => { const result = await api.managerStatus(id, status); setOrder(result.order); };
  const saveOps=async(markContacted=false)=>{const result=await api.patchManagerOps(id,{...ops,markContacted});setOps(result.ops);setSaved(true);setTimeout(()=>setSaved(false),1600)};
  const chooseOperation=(operationType:'none'|'reschedule'|'cancel'|'no_show')=>setWorkflow(current=>({...current,operationType,requestedDate:operationType==='reschedule'?current.requestedDate:'',workflowStatus:operationType==='none'?'Нет запроса':'Запрошено'}));
  const saveWorkflow=async()=>{setWorkflowBusy(true);setError('');try{const result=await api.patchOrderWorkflow(id,workflow);setWorkflow(result.workflow);setWorkflowSaved(true);setTimeout(()=>setWorkflowSaved(false),1800)}catch(e:any){setError(e.message||'Не удалось сохранить операцию')}finally{setWorkflowBusy(false)}};
  if (error && !order) return <Notice>{error}</Notice>; if (!order) return <SkeletonCards />;
  const workflowLabels:Record<string,string>={none:'Без операции',reschedule:'Перенос',cancel:'Отмена',no_show:'Неявка'};
  return <>
    <section className="px-order-detail-grid"><Detail label="Экскурсия" value={order.tourTitle} /><Detail label="Дата" value={order.selectedDate} /><Detail label="Клиент" value={order.customer} /><Detail label="Контакт" value={order.contact} /><Detail label="Отель" value={order.hotel} /><Detail label="Источник" value={order.source} /><Detail label="Сумма" value={formatUsd(order.totalMinor)} /><Detail label="Оплачено" value={formatUsd(order.paidMinor)} /><Detail label="Осталось" value={formatUsd(order.remainingMinor)} /></section>
    <section className="px-section px-office-actions"><h2>Статус заказа</h2><div>{(['Новый', 'Оплачено', 'Подтверждено'] as OrderSummary['status'][]).map((status) => <button key={status} className={order.status === status ? 'active' : ''} onClick={() => update(status)}>{status}</button>)}</div><p>Статус сохраняется в D1, фиксируется в журнале действий и сразу виден владельцу.</p></section>
    <section className="px-section px-manager-editor"><div><span className="px-kicker">РАБОТА МЕНЕДЖЕРА</span><h2>Исполнение заказа</h2><p>Менеджер отвечает за коммуникацию, точку сбора и внутренние детали. Цена и программа остаются зоной администратора.</p></div><label className="px-field"><span>Ответственный менеджер</span><select value={ops.assignedManager} onChange={e=>setOps({...ops,assignedManager:e.target.value})}><option value="">Не назначен</option>{staff.map(item=><option key={item.telegramUserId} value={item.displayName}>{item.displayName} · {item.role}</option>)}</select></label><label className="px-field"><span>Трансфер / точка сбора</span><input value={ops.pickupNote} onChange={e=>setOps({...ops,pickupNote:e.target.value})} placeholder="Уточнение по отелю и времени" /></label><label className="px-field"><span>Внутренняя заметка</span><textarea rows={5} value={ops.internalNote} onChange={e=>setOps({...ops,internalNote:e.target.value})} placeholder="Что важно передать следующей смене или гиду" /></label><div className="px-manager-edit-actions"><button className="px-button px-button-dark" onClick={()=>saveOps(false)}>{saved?'Сохранено ✓':'Сохранить изменения'}</button><button className="px-button px-button-primary" onClick={()=>saveOps(true)}>Связались с клиентом</button></div>{ops.lastContactAt&&<p className="px-form-note">Последний контакт: {new Date(ops.lastContactAt).toLocaleString('ru-RU')}</p>}</section>
    <section className="px-section px-order-workflow"><div className="px-workflow-head"><div><span className="px-kicker">ПЕРЕНОС / ОТМЕНА · DEMO</span><h2>Изменение поездки</h2><p>Внутренний workflow уже работает в D1. Он фиксирует запрос и решение менеджера, не подменяя реальный возврат средств.</p></div><span className="px-workflow-state">{workflow.workflowStatus}</span></div><div className="px-workflow-choice">{(['none','reschedule','cancel','no_show'] as const).map(type=><button key={type} className={workflow.operationType===type?'active':''} onClick={()=>chooseOperation(type)}><b>{workflowLabels[type]}</b><span>{type==='none'?'Обычное исполнение':type==='reschedule'?'Новая дата поездки':type==='cancel'?'Запрос на отмену':'Клиент не пришёл на выезд'}</span></button>)}</div>{workflow.operationType!=='none'&&<div className="px-workflow-editor">{workflow.operationType==='reschedule'&&<label className="px-field"><span>Новая желаемая дата</span><input type="date" value={workflow.requestedDate} onChange={e=>setWorkflow({...workflow,requestedDate:e.target.value})}/></label>}<label className="px-field"><span>Причина / запрос клиента</span><textarea rows={3} value={workflow.reason} onChange={e=>setWorkflow({...workflow,reason:e.target.value})} placeholder={workflow.operationType==='cancel'?'Почему клиент просит отмену':workflow.operationType==='no_show'?'Что известно о неявке':'Почему нужен перенос'}/></label><label className="px-field"><span>Решение / заметка менеджера</span><textarea rows={3} value={workflow.managerNote} onChange={e=>setWorkflow({...workflow,managerNote:e.target.value})} placeholder="Что согласовано, что нужно проверить"/></label><label className="px-field"><span>Статус согласования</span><select value={workflow.workflowStatus} onChange={e=>setWorkflow({...workflow,workflowStatus:e.target.value})}><option>Запрошено</option><option>Согласовано</option><option>Отклонено</option></select></label>{(workflow.operationType==='cancel'||workflow.operationType==='no_show')&&order.paidMinor>0&&<div className="px-workflow-warning"><b>Оплата уже зафиксирована: {formatUsd(order.paidMinor)}</b><span>{workflow.operationType==='cancel'?'DEMO-отмена не создаёт фиктивный refund. Возврат будет выполняться только через реальный платёжный провайдер после интеграции.':'Неявка фиксируется как операционное событие. Удержание/возврат в реальной системе применяется только по подтверждённым правилам и платёжным данным.'}</span></div>}</div>}<button className="px-button px-button-dark px-block" disabled={workflowBusy} onClick={saveWorkflow}>{workflowBusy?'Сохраняем…':workflowSaved?'Операция сохранена ✓':'Сохранить операцию'}</button>{workflow.updatedAt&&<p className="px-form-note">Последнее изменение: {new Date(workflow.updatedAt).toLocaleString('ru-RU')} · записано в audit log владельца.</p>}{error&&<Notice>{error}</Notice>}</section>
  </>;
}

function ChannelsPage() { return <><section className="px-channel-proof"><div className="px-channel-source"><span className="px-kicker">КАНАЛ 01</span><h2>Telegram Mini App</h2><p>Каталог → дата → участники → бронь → DEMO-оплата</p></div><div className="px-channel-arrow">→</div><div className="px-channel-core"><span>ЕДИНАЯ</span><b>Система бронирований</b><p>Один каталог, заказы, клиенты, статусы и аналитика</p></div><div className="px-channel-arrow">←</div><div className="px-channel-source"><span className="px-kicker">КАНАЛ 02</span><h2>Сайт / Tilda</h2><p>Будущий второй вход в ту же очередь заказов</p></div><div className="px-channel-manager"><span>↓</span><b>Команда MAX TOUR</b><p>Менеджер исполняет заказ, администратор управляет продуктом, владелец видит показатели.</p></div></section><section className="px-integration-grid"><article className="ready"><span>ИНТЕРФЕЙС ГОТОВ</span><h3>Telegram Bot</h3><p>Mini App работает в браузере и Telegram WebView.</p><b>КОД ГОТОВ → нужны bot token + chat IDs для реальной доставки</b></article><article className="ready"><span>АРХИТЕКТУРА ГОТОВА</span><h3>Tilda → D1</h3><p>Единая модель заказа уже существует.</p><b>WEBHOOK ГОТОВ → нужны secret + mapping реальных полей форм</b></article><article className="demo"><span>DEMO FLOW ГОТОВ</span><h3>Оплата</h3><p>Расчёт, заказ, paid/remaining и payment state уже работают.</p><b>ЗАГЛУШКА → нужен выбранный provider + callbacks/webhooks</b></article><article className="demo"><span>UI + D1 ГОТОВЫ</span><h3>Расписание и места</h3><p>Администратор меняет DEMO availability.</p><b>ЗАГЛУШКА → нужен авторитетный live-источник + seat locking</b></article><article className="demo"><span>ПРАВИЛА ГОТОВЫ</span><h3>Уведомления / SLA</h3><p>Владелец задаёт SLA и режим уведомлений.</p><b>SLA И OUTBOX ГОТОВЫ → нужны реальные Telegram chat IDs</b></article></section></>; }

function AdminPage() { const navigate = useNavigate(); const { items, loading, error } = useTours(true); const [title, setTitle] = useState(''); const [busy, setBusy] = useState(false); const { bump } = useApp(); const add = async () => { if (!title.trim()) return; setBusy(true); try { await api.addTour({ title: title.trim(), direction: 'Нячанг', description: 'DEMO-экскурсия, созданная администратором.', priceMode: 'dynamic-request', adultMinor: 0, scheduleMode: 'request', images: [], published: true }); setTitle(''); bump(); } finally { setBusy(false); } }; return <><section className="px-metric-grid"><Metric label="Экскурсий" value={String(items.length)} note="в demo-каталоге" /><Metric label="Опубликовано" value={String(items.filter((t) => t.published).length)} note="видно туристу" /><Metric label="Направлений" value={String(new Set(items.map((t) => t.direction)).size)} note="масштабирование" /></section><section className="px-admin-add"><div><span className="px-kicker">БЫСТРОЕ ДОБАВЛЕНИЕ</span><h2>Новая DEMO-экскурсия</h2></div><input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Название экскурсии" /><button className="px-button px-button-dark" disabled={busy} onClick={add}>Добавить</button></section>{error && <Notice>{error}</Notice>}{loading ? <SkeletonCards /> : <section className="px-admin-tour-list">{items.map((tour) => <button key={tour.id} onClick={() => navigate(`/admin/tours/${tour.id}`)}><img src={tour.images[0]} alt="" /><div><span>{tour.direction} · {tour.dataStatus}</span><h3>{tour.title}</h3><p>{tour.published ? 'Опубликовано' : 'Черновик'} · {formatUsd(tour.pricingRules.adultMinor ?? tour.pricingRules.adultFromMinor ?? 0)}</p></div><em>Редактировать →</em></button>)}</section>}</>; }

function AdminTourPage() {
  const { id = '' } = useParams(); const { bump } = useApp(); const [tour, setTour] = useState<Tour | null>(null);
  const [title,setTitle]=useState(''); const [price,setPrice]=useState(''); const [description,setDescription]=useState(''); const [published,setPublished]=useState(true); const [program,setProgram]=useState(''); const [included,setIncluded]=useState(''); const [extraCosts,setExtraCosts]=useState(''); const [whatToTake,setWhatToTake]=useState(''); const [images,setImages]=useState(''); const [saved,setSaved]=useState(false);
  useEffect(()=>{api.tour(id).then((r)=>{setTour(r.item);setTitle(r.item.title);setPrice(String((r.item.pricingRules.adultMinor??r.item.pricingRules.adultFromMinor??0)/100));setDescription(r.item.description);setPublished(r.item.published);setProgram(r.item.program.join('\n'));setIncluded(r.item.included.join('\n'));setExtraCosts(r.item.extraCosts.join('\n'));setWhatToTake(r.item.whatToTake.join('\n'));setImages(r.item.images.join('\n'))})},[id]);
  if(!tour)return <SkeletonCards/>;
  const lines=(value:string)=>value.split('\n').map(x=>x.trim()).filter(Boolean);
  const save=async()=>{const adultMinor=Math.round(Number(price)*100);const result=await api.patchTour(tour.id,{title,description,published,adultMinor,program:lines(program),included:lines(included),extraCosts:lines(extraCosts),whatToTake:lines(whatToTake),images:lines(images)});setTour(result.item);setSaved(true);bump();setTimeout(()=>setSaved(false),1800)};
  return <section className="px-edit-form"><div className="px-edit-preview"><img src={lines(images)[0]||tour.images[0]} alt={tour.title}/><div><span className="px-kicker">LIVE DEMO PREVIEW</span><h2>{title||tour.title}</h2><p>Все изменения этой формы сохраняются в D1 как override текущей demo-сессии.</p></div></div><div className="px-admin-editor-grid"><label className="px-field"><span>Название</span><input value={title} onChange={e=>setTitle(e.target.value)}/></label><label className="px-field"><span>Цена взрослого, $</span><input type="number" value={price} onChange={e=>setPrice(e.target.value)}/></label></div><label className="px-field"><span>Описание</span><textarea rows={5} value={description} onChange={e=>setDescription(e.target.value)}/></label><label className="px-field"><span>Программа — один пункт на строку</span><textarea rows={10} value={program} onChange={e=>setProgram(e.target.value)}/></label><div className="px-admin-editor-grid"><label className="px-field"><span>Включено — по строкам</span><textarea rows={8} value={included} onChange={e=>setIncluded(e.target.value)}/></label><label className="px-field"><span>Доплаты — по строкам</span><textarea rows={8} value={extraCosts} onChange={e=>setExtraCosts(e.target.value)}/></label></div><label className="px-field"><span>Что взять — по строкам</span><textarea rows={7} value={whatToTake} onChange={e=>setWhatToTake(e.target.value)}/></label><label className="px-field"><span>Галерея — URL, один на строку; порядок строк = порядок фото</span><textarea rows={9} value={images} onChange={e=>setImages(e.target.value)}/></label><label className="px-owner-check"><input type="checkbox" checked={published} onChange={e=>setPublished(e.target.checked)}/><span>Показывать экскурсию туристу</span></label><button className="px-button px-button-dark px-block" onClick={save}>{saved?'Сохранено ✓':'Сохранить все изменения'}</button><p className="px-form-note">Для production вместо URL-поля галереи будет загрузка в собственное хранилище Cloudflare с сортировкой файлов.</p></section>;
}

function SchedulePage() { const { items } = useTours(true); const { bump } = useApp(); const [tourId, setTourId] = useState('dalat-premium'); const [date, setDate] = useState('2026-09-20'); const [status, setStatus] = useState<'available' | 'low' | 'request'>('available'); const [promo, setPromo] = useState(false); const [label, setLabel] = useState('SPECIAL DEMO'); const [value, setValue] = useState('-10%'); const saveDate = async () => { await api.schedule(tourId, { date, status }); bump(); }; const savePromo = async () => { await api.promo(tourId, { enabled: promo, label, value }); bump(); }; return <div className="px-admin-columns"><section className="px-admin-panel"><span className="px-kicker">DEMO AVAILABILITY</span><h2>Дата и доступность</h2><label className="px-field"><span>Экскурсия</span><select value={tourId} onChange={(e) => setTourId(e.target.value)}>{items.map((tour) => <option key={tour.id} value={tour.id}>{tour.title}</option>)}</select></label><label className="px-field"><span>Дата</span><input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></label><label className="px-field"><span>Статус</span><select value={status} onChange={(e) => setStatus(e.target.value as typeof status)}><option value="available">доступно</option><option value="low">мало мест</option><option value="request">по запросу</option></select></label><button className="px-button px-button-dark" onClick={saveDate}>Сохранить дату</button></section><section className="px-admin-panel"><span className="px-kicker">DEMO PROMO</span><h2>Акция</h2><label className="px-toggle"><input type="checkbox" checked={promo} onChange={(e) => setPromo(e.target.checked)} /><span />Включить DEMO promo</label><label className="px-field"><span>Название</span><input value={label} onChange={(e) => setLabel(e.target.value)} /></label><label className="px-field"><span>Значение</span><input value={value} onChange={(e) => setValue(e.target.value)} /></label><button className="px-button px-button-dark" onClick={savePromo}>Сохранить акцию</button><p className="px-form-note">Это демонстрационные данные и не выдаются за текущую акцию MAX TOUR.</p></section></div>; }

function AnalyticsPage() { const [data, setData] = useState<AnalyticsResponse | null>(null); const [source, setSource] = useState('Все'); useEffect(() => { const params = new URLSearchParams(); if (source !== 'Все') params.set('source', source); api.analytics(params).then(setData); }, [source]); if (!data) return <SkeletonCards />; const metrics = data.metrics; const maxSource = Math.max(1, ...data.sources.map((row) => row.orders)); return <><section className="px-analytics-head"><div><span className="px-kicker">DEMO ANALYTICS</span><h2>От источника до оплаты</h2></div><select value={source} onChange={(e) => setSource(e.target.value)}><option>Все</option><option>Telegram</option><option>Сайт</option><option>Реклама</option><option>Другие каналы</option></select></section><section className="px-metric-grid px-metric-grid-4"><Metric label="Просмотры" value={String(metrics.views)} note="DEMO" /><Metric label="Начали бронь" value={String(metrics.started)} note="DEMO" /><Metric label="Оплаты" value={String(metrics.paid)} note="DEMO" /><Metric label="Выручка" value={formatUsd(metrics.revenueMinor)} note="DEMO" /></section><section className="px-analytics-grid"><article><span className="px-kicker">ВОРОНКА</span>{data.funnel.map((item) => <div className="px-funnel-row" key={item.stage}><span>{item.stage}</span><b>{item.value}</b><i style={{ width: `${Math.max(8, (item.value / Math.max(1, data.funnel[0]?.value || 1)) * 100)}%` }} /></div>)}</article><article><span className="px-kicker">ИСТОЧНИКИ</span>{data.sources.map((row) => <div className="px-source-row" key={row.source}><div><b>{row.source}</b><span>{row.orders} заказов · {formatUsd(row.revenueMinor)}</span></div><i><em style={{ width: `${(row.orders / maxSource) * 100}%` }} /></i></div>)}</article></section><section className="px-section px-note-panel"><p>Все показатели на этой странице — демонстрационные. Они показывают будущую структуру аналитики source → tour → order → payment, а не исторические результаты MAX TOUR.</p></section></>; }

function DirectionsPage() { const [items, setItems] = useState<Destination[]>([]); const [name, setName] = useState(''); const load = () => { void api.directions().then((r) => setItems(r.items)); }; useEffect(load, []); const add = async () => { if (!name.trim()) return; await api.addDirection(name.trim()); setName(''); load(); }; return <><section className="px-direction-grid">{items.map((item, index) => <article key={item.id}><span>{String(index + 1).padStart(2, '0')}</span><h3>{item.name}</h3><p>{item.dataStatus}</p></article>)}</section><section className="px-admin-add"><div><span className="px-kicker">МАСШТАБИРОВАНИЕ</span><h2>Новое DEMO-направление</h2></div><input value={name} onChange={(e) => setName(e.target.value)} placeholder="Например: Хошимин" /><button className="px-button px-button-dark" onClick={add}>Добавить</button></section></>; }

function Metric({ label, value, note }: { label: string; value: string; note: string }) { return <article className="px-metric"><span>{label}</span><b>{value}</b><small>{note}</small></article>; }
function Detail({ label, value }: { label: string; value: React.ReactNode }) { return <div className="px-detail-cell"><span>{label}</span><b>{value}</b></div>; }
function Notice({ children }: { children: React.ReactNode }) { return <div className="px-notice">{children}</div>; }
